{
  "headline": "Focus on clean indoor air and fitted N95 masks at {{level.name}} air quality",
  "summary": "Today's air sits at {{level.name}} with current US AQI {{aqi.now}}. Running filtration indoors delivers {{impact.buy_hepa_purifier.pct}} lower exposure, while your cleanest outdoor window is {{best.start}} to {{best.end}}.",
  "cards": [
    {
      "actionId": "buy_hepa_purifier",
      "title": "Run a true HEPA purifier in the main room",
      "why": "Continuous mechanical filtration gives the strongest drop in breathed PM2.5 indoors.",
      "when": "Keep running across sleeping and home hours.",
      "steps": [
        "Close bedroom doors to reduce treated volume.",
        "Keep ionizer modes turned off."
      ]
    },
    {
      "actionId": "air_house_in_best_window",
      "title": "Manage windows around peak smog",
      "why": "Shutting windows during {{avoid.start}} to {{avoid.end}} slows outdoor smoke infiltration.",
      "when": "Open briefly at {{best.start}} only if air is moderate.",
      "steps": [
        "Close windows well before dusk.",
        "Turn off exhaust fans after cooking."
      ]
    },
    {
      "actionId": "no_idling",
      "title": "Avoid unnecessary vehicle idling",
      "why": "Idling vehicles release harmful pollutants and CO2e without moving.",
      "when": "Whenever stopped for more than a minute.",
      "steps": [
        "Turn off the engine if you expect to stop for a while.",
        "Inform drivers about the impact of idling."
      ]
    },
    {
      "actionId": "cooking_ventilation",
      "title": "Ventilate well during and after cooking",
      "why": "Cooking can release fine particles and gases indoors.",
      "when": "Always during and for a period after cooking.",
      "steps": [
        "Use your kitchen exhaust fan.",
        "Open a window slightly if no fan is available."
      ]
    },
    {
      "actionId": "community_no_burning",
      "title": "Advocate for community anti-burning measures",
      "why": "Reducing open burning in the neighborhood directly lowers regional air pollution.",
      "when": "Before the next community meeting.",
      "steps": [
        "Discuss with neighbors and local authorities.",
        "Support initiatives for cleaner fuel alternatives."
      ]
    },
    {
      "actionId": "damp_mop_dont_sweep",
      "title": "Damp mop instead of sweeping",
      "why": "Sweeping stirs up settled dust and particles, worsening indoor air quality.",
      "when": "For all floor cleaning.",
      "steps": [
        "Use a damp cloth or mop.",
        "Focus on surfaces where dust accumulates."
      ]
    },
    {
      "actionId": "share_community_brief",
      "title": "Share the Community Brief with your RWA",
      "why": "Coordinated anti-burning and dust control protects every family on the street.",
      "when": "Share before the next society meeting.",
      "steps": [
        "Print the single-page brief.",
        "Post in society and school parent groups."
      ]
    }
  ],
  "memberNotes": [
    {
      "group": "child",
      "note": "Keep children's outdoor play indoors while level remains {{level.name}}."
    },
    {
      "group": "respiratory",
      "note": "Keep rescue inhaler handy and avoid strenuous outdoor trips."
    }
  ],
  "tradeoffs": [
    "Avoiding vehicle idling saves {{co2e.no_idling}} and reduces local pollution."
  ]
}
